brand.css:
:root{--brand-hover:#0055A0;--brand-tint:#E9F3FF}
body .primary:hover{background:var(--brand-hover)}body nav button[aria-current=step],body .pill{background:var(--brand-tint);color:var(--primary)}body .choice:has(input:checked){background:var(--brand-tint)}body .dark .eyebrow{color:#FFFFFF}
body #brand{font-size:24px;letter-spacing:.035em;max-width:290px;display:block;line-height:1.1}body .hero img{border-radius:8px}body .hero h1{font-weight:800;letter-spacing:-.04em}
